<?php
declare(strict_types=1);
require_once __DIR__.'/CommerceProductionService.php';
require_once __DIR__.'/CommercePricingService.php';
/** Production-centered UI; commands still use shared guarded inventory/schedule services. */
final class CommerceProductionExperience
{
    private static function e(mixed $v):string{return CommerceExperience::e($v);}
    private static function rows(PDO $db,string $sql,array $args=[]):array{$q=$db->prepare($sql);$q->execute($args);return$q->fetchAll();}
    private static function money(int $n,string $currency):string{return self::e($currency).' '.number_format($n/100,2);}
    private static function link(string $tab,string $label,array $args=[],bool $drawer=false):string{return '<a '.($drawer?'data-commerce-drawer-link ':'').'href="'.self::e(CommerceExperience::url($tab,$args)).'">'.self::e($label).'</a>';}
    public static function hub(PDO $db,array $u,int $org,bool $manage,string $base):void
    {
        if($manage)CommerceAccess::demand($db,$u,$org,'inventory');
        $groups=CommerceProductionService::productions($db,$u,$org);$q=mb_substr(trim((string)($_GET['q']??'')),0,190);$filter=(string)($_GET['sales_filter']??'all');$tab=$manage?'performances':'overview';
        echo '<div class="commerce-heading"><div><h1>'.($manage?'Productions & Performances':'Production ticket sales').'</h1><p>Sales and availability by actual showtime.</p></div>';if(CommerceAccess::can($db,$u,$org,'inventory'))echo '<div class="commerce-actions">'.self::link('add_performance','Add Performance',[],true).'</div>';echo '</div>';
        echo '<form method="get" class="commerce-filter"><input type="hidden" name="tab" value="'.$tab.'">';CommerceExperience::input('q','Find production or venue','search',$q,'maxlength="190"');echo '<label>Performances<select name="sales_filter">';foreach(['all'=>'All performances','on_sale'=>'On sale','needs_attention'=>'Needs attention','sold_out'=>'Sold out'] as $value=>$name)echo '<option value="'.$value.'" '.($filter===$value?'selected':'').'>'.$name.'</option>';echo '</select></label><button>Filter</button></form><p class="commerce-muted">Physical capacity includes sold, held and allocated positions. Sellable availability excludes closed or unready shows. Revenue is net of confirmed refunds and includes fees and tax.</p>';
        $active=[];$past=[];
        foreach($groups as $p){if($q!==''&&mb_stripos($p['title'].' '.implode(' ',$p['venues']),$q)===false)continue;$original=$p['shows'];$p['range']=array_column($original,'starts_at');if($filter!=='all')$p['shows']=array_values(array_filter($p['shows'],fn($show)=>match($filter){'on_sale'=>$show['sellable']>0,'sold_out'=>$show['sold_out'],'needs_attention'=>$show['problem']!==null||(!$show['sold_out']&&$show['sellable']===0),default=>true}));if(!$p['shows']&&$original)continue;if($p['past'])$past[]=$p;else$active[]=$p;}
        if(!$active)echo '<p class="commerce-empty">No active productions match this view. Adjust the filter or add a performance.</p>';
        foreach($active as $p)self::card($db,$u,$org,$p,$manage,$base);
        echo '<details class="commerce-past-productions"><summary>Past productions ('.count($past).')</summary>';foreach($past as $p)self::card($db,$u,$org,$p,$manage,$base);if(!$past)echo '<p>No past productions match.</p>';echo '</details>';
    }
    private static function card(PDO $db,array $u,int $org,array $p,bool $manage,string $base):void
    {
        echo '<article class="commerce-production-card"><header class="commerce-production-card-header">';if($manage&&$p['has_poster']&&$p['announcement_published_at'])echo '<img class="commerce-production-thumbnail" alt="" src="'.self::e($base.'/production-poster?id='.(int)$p['id']).'">';echo '<div><h2>'.self::e($p['title']).'</h2><p>'.self::e(implode(' · ',$p['venues'])?:'Venue not yet scheduled').'</p>';if($p['shows']){$times=$p['range']??array_column($p['shows'],'starts_at');sort($times);echo '<p class="commerce-muted">'.self::e(substr($times[0],0,10).' – '.substr($times[count($times)-1],0,10)).'</p>';}echo '</div></header>';
        $n=$p['totals'];echo '<div class="commerce-production-totals"><span><strong>'.$n['sold'].' / '.$n['capacity'].'</strong> sold / physical capacity</span><span><strong>'.$n['sellable'].'</strong> sellable now</span><span>'.$n['held'].' held · '.$n['blocked'].' allocated</span>';foreach($p['revenue'] as $currency=>$net)echo '<span><strong>'.self::money($net,$currency).'</strong> net revenue</span>';echo '</div>';
        if(CommerceAccess::can($db,$u,$org,'inventory')&&!in_array($p['lifecycle_stage'],['archived','completed'],true))echo '<div class="commerce-actions">'.self::link('add_performance','Add Performance',['production'=>$p['id']],true).' '.self::link('pricing','Production pricing',['production'=>$p['id']],true).'</div>';
        if(!$p['shows'])echo '<p>No performances scheduled.</p>';
        $date='';foreach($p['shows'] as $show){$day=substr($show['starts_at'],0,10);if($date!==$day){echo '<h3 class="commerce-date-heading">'.self::e((new DateTimeImmutable($day))->format('D, M j, Y')).'</h3>';$date=$day;}echo '<div class="commerce-production-showtime"><div>';if(CommerceAccess::can($db,$u,$org,'inventory'))echo self::link('performance',(new DateTimeImmutable($show['starts_at']))->format('g:i A'),['id'=>$show['id']],true);else echo '<strong>'.self::e((new DateTimeImmutable($show['starts_at']))->format('g:i A')).'</strong>';echo ''.(count($p['venues'])>1?'<small>'.self::e($show['venue'].' / '.$show['space_name']).'</small>':'').'<small>'.self::e(explode(' · ',CommercePerformancePolicy::label($show),2)[1]??'Timezone review needed').'</small></div><div><strong>'.$show['sold'].' / '.$show['capacity'].'</strong> sold<small>'.$show['sellable'].' sellable · '.$show['held'].' held · '.$show['blocked'].' allocated</small></div><div><span class="commerce-status">'.self::e($show['readiness']).'</span>';if(isset($show['net_minor']))echo '<small>'.self::money($show['net_minor'],$show['currency']).' net'.($show['refunded_minor']?' · '.self::money($show['refunded_minor'],$show['currency']).' returned':'').'</small>';echo '</div>';if(CommerceAccess::can($db,$u,$org,'inventory'))echo '<div>'.self::link('performance','Manage',['id'=>$show['id']],true).'</div>';echo '</div>';}
        if((string)($_GET['sales_filter']??'all')!=='all')echo '<p class="commerce-muted">Production totals include all performances, including those hidden by this filter.</p>';echo '</article>';
    }
    public static function priceEditor(array $prices):void
    {
        echo '<fieldset data-price-editor><legend>Ticket categories & prices by zone</legend><div data-price-rows>';$index=0;foreach($prices as $zone=>$categories)foreach($categories as $category=>$minor)self::priceRow($index++,(string)$zone,(string)$category,$minor===null?'':number_format($minor/100,2,'.',''));echo '</div><button type="button" data-add-price>Add ticket category / zone</button><p>Amounts are in the organization currency. Every physical seating zone needs at least one category.</p></fieldset>';
    }
    private static function priceRow(int $i,string $zone,string $category,string $amount):void
    {
        echo '<div class="commerce-price-row" data-price-row>';CommerceExperience::input('price_rows['.$i.'][zone]','Seating zone','text',$zone,'required pattern="[a-zA-Z0-9_-]{1,80}" maxlength="80"');CommerceExperience::input('price_rows['.$i.'][category]','Ticket category','text',$category,'required pattern="[a-zA-Z0-9 _-]{1,60}" maxlength="60"');CommerceExperience::input('price_rows['.$i.'][amount]','Price','number',$amount,'required min="0" max="10000" step="0.01" inputmode="decimal"');echo '<button type="button" data-remove-price>Remove</button></div>';
    }
    public static function add(PDO $db,array $u,int $org):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');$production=(int)($_GET['production']??0);$draft=null;$draftKey=(string)($_GET['draft']??'');if($draftKey!==''){$draft=$_SESSION['commerce_planning'][$draftKey]??null;if(!$draft||$draft['org']!==$org||$draft['actor']!==(int)$u['id']||$draft['type']!=='schedule'||$draft['created']<time()-1200)throw new RuntimeException('Schedule draft expired. Start again.');$production=(int)$draft['production'];}$productions=self::rows($db,"SELECT id,title FROM productions WHERE lifecycle_stage IN ('planning','upcoming','in_production','performing') ORDER BY title");$layouts=self::rows($db,"SELECT l.*,s.id space_id,s.name space_name,v.name venue,v.timezone_name FROM commerce_layouts l JOIN commerce_spaces s ON s.id=l.space_id AND s.organization_id=l.organization_id JOIN commerce_venues v ON v.id=s.venue_id AND v.organization_id=s.organization_id WHERE l.organization_id=? AND l.status='published' ORDER BY v.name,s.name,l.version_number DESC",[$org]);
        echo '<div data-production-drawer><h2>Add Performance</h2><p>Add exact showtimes, then review duplicates, venue conflicts and timezone offsets. New sales start closed.</p>';if(!$layouts){echo '<p>Publish a seating layout in Settings before scheduling.</p></div>';return;}
        $defaultMap=[];if(CommercePricingService::ready($db))foreach($productions as $p){$d=CommercePricingService::defaults($db,$org,(int)$p['id']);if($d)$defaultMap[$p['id']]=$d['prices'];}echo '<script type="application/json" data-production-defaults>'.json_encode($defaultMap,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';CommerceExperience::form('schedule_review',['drawer'=>'1']);echo '<label>Production<select name="production" required data-production-choice><option value="">Choose production</option>';foreach($productions as $p)echo '<option value="'.$p['id'].'" '.($production===(int)$p['id']?'selected':'').'>'.self::e($p['title']).'</option>';echo '</select></label><label data-space-filter>Venue / performance space<select data-space-choice><option value="">All spaces</option>';$spaces=[];foreach($layouts as $l)$spaces[$l['space_id']]=$l['venue'].' / '.$l['space_name'];foreach($spaces as $id=>$name)echo '<option value="'.$id.'">'.self::e($name).'</option>';echo '</select></label><label>Published seating layout<select name="layout" required data-schedule-layout>';foreach($layouts as $l)echo '<option '.($draft&&(int)$draft['layout']===(int)$l['id']?'selected ':'').'value="'.$l['id'].'" data-space="'.$l['space_id'].'" data-zones="'.self::e(implode(', ',array_unique(array_column(array_filter(json_decode($l['document_json'],true)['items'],fn($item)=>$item['kind']==='seat'),'zone')))).'" data-timezone="'.self::e(CommercePerformancePolicy::venueTimezone($db,$org,(int)$l['id'])).'">'.self::e($l['venue'].' / '.$l['space_name'].' · version '.$l['version_number']).'</option>';echo '</select></label><p data-schedule-zones></p><p data-schedule-timezone role="status">Venue timezone: '.self::e(CommercePerformancePolicy::venueTimezone($db,$org,(int)($draft['layout']??$layouts[0]['id']))).'</p><label>Seating mode<select name="seating_mode"><option value="reserved">Reserved seating</option><option value="general_admission" '.(($draft['input']['seating_mode']??'')==='general_admission'?'selected':'').'>General admission</option></select></label><fieldset><legend>Selected showtimes</legend><div data-compact-showtimes>';if($draft){foreach($draft['input']['dates'] as $i=>$date)self::showtime((string)$date,(string)($draft['input']['times'][$i]??''),(string)($draft['input']['offsets'][$i]??''));}else self::showtime();echo '</div><button type="button" data-add-compact-showtime>Add another date / time</button></fieldset><details><summary>Daylight-saving time</summary><p>Nonexistent local times are rejected. For repeated times choose an occurrence or enter an explicit offset on that row.</p><label>Repeated local hour<select name="dst_choice"><option value="">Require an explicit choice</option><option value="earlier" '.(($draft['input']['dst_choice']??'')==='earlier'?'selected':'').'>First occurrence</option><option value="later" '.(($draft['input']['dst_choice']??'')==='later'?'selected':'').'>Second occurrence</option></select></label></details>';
        $defaults=CommercePricingService::ready($db)&&$production?CommercePricingService::defaults($db,$org,$production):null;$inherit=($draft['input']['pricing_source']??($defaults?'production':'override'))==='production';echo '<label>Pricing source<select name="pricing_source" data-pricing-source><option value="production" '.(!$defaults?'disabled':($inherit?'selected':'')).'>Inherit production defaults</option><option value="override" '.(!$inherit?'selected':'').'>Set prices for these performances</option></select></label>';
        $existing=$production?self::rows($db,'SELECT prices_json FROM commerce_performances WHERE organization_id=? AND production_id=? ORDER BY id DESC LIMIT 1',[$org,$production]):[];$prices=$draft['prices']??$defaults['prices']??($existing?json_decode($existing[0]['prices_json'],true):[]);if(!$prices){$doc=json_decode($layouts[0]['document_json'],true);foreach($doc['items'] as $item)if($item['kind']==='seat')$prices[$item['zone']]=['Adult'=>null];}self::priceEditor($prices);echo '<button>Review performances</button></form></div>';
    }
    private static function showtime(string $date='',string $time='',string $offset=''):void
    {echo '<div class="commerce-compact-showtime" data-compact-showtime><label>Date<input name="dates[]" type="date" value="'.self::e($date).'" required></label><label>Time<input name="times[]" type="time" value="'.self::e($time).'" required step="60"></label><label>UTC offset if needed<input name="offsets[]" value="'.self::e($offset).'" maxlength="6" placeholder="-04:00"></label><button type="button" data-remove-compact-showtime>Remove</button></div>';}
    public static function pricing(PDO $db,array $u,int $org):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');echo '<div data-production-drawer><h2>Production pricing</h2>';if(!CommercePricingService::ready($db)){echo '<p>Pricing inheritance requires migration 110. Existing performance prices remain unchanged.</p></div>';return;}
        $production=(int)($_GET['production']??0);$groups=CommerceProductionService::productions($db,$u,$org);$p=null;foreach($groups as $candidate)if((int)$candidate['id']===$production)$p=$candidate;if(!$p)throw new RuntimeException('Production unavailable.');echo '<p>'.self::e($p['title']).'</p>';
        if(isset($_GET['pricing_review'])){self::pricingReview($db,$u,$org,(string)$_GET['pricing_review']);echo '</div>';return;}
        $defaults=CommercePricingService::defaults($db,$org,$production);echo '<p>Currency: '.self::e(CommerceStore::organization($db,$org)['currency']).'</p>';$selected=(int)($_GET['id']??0);$prices=$defaults['prices']??($p['shows']?json_decode($p['shows'][0]['prices_json'],true):['standard'=>['Adult'=>null]]);if($selected)foreach($p['shows'] as $show)if((int)$show['id']===$selected)$prices=json_decode($show['prices_json'],true);
        echo '<p>Production defaults: '.($defaults?'revision '.$defaults['revision']:'not set').'. Existing performances keep their prices until explicitly set to inherit.</p>';CommerceExperience::form('pricing_review',['production'=>$production]);echo '<label>Apply prices to<select name="pricing_mode" data-pricing-mode>';foreach(['defaults'=>'Production defaults & future inheriting performances','override'=>'Selected performances · override','inherit'=>'Selected performances · inherit defaults'] as $mode=>$label)echo '<option value="'.$mode.'" '.(($selected&&$mode==='override')||(!$selected&&$mode==='defaults')?'selected':'').'>'.self::e($label).'</option>';echo '</select></label><fieldset data-pricing-selection><legend>Affected performances</legend>';foreach($p['shows'] as $show)if(in_array($show['schedule_status'],['scheduled','draft'],true)&&$show['starts_at_utc']>gmdate('Y-m-d H:i:s'))echo '<label><input type="checkbox" name="performances[]" value="'.$show['id'].'" '.($selected===(int)$show['id']?'checked':'').'>'.self::e(CommercePerformancePolicy::label($show)).'</label>';echo '</fieldset>';self::priceEditor($prices);CommerceExperience::input('reason','Reason for pricing change','text','','required maxlength="500"');echo '<label><input type="checkbox" name="acknowledge_orders" value="1"> Existing orders keep their saved prices, including paid, held and pending orders. Apply changes only to future reservations.</label><button>Review pricing changes</button></form></div>';
    }
    private static function reviewed(array $u,int $org,string $key):array
    {$r=$_SESSION['commerce_price_reviews'][$key]??null;if(!$r||$r['org']!==$org||$r['actor']!==(int)$u['id']||$r['created']<time()-1200)throw new RuntimeException('Pricing review expired. Start again.');return$r;}
    private static function pricingReview(PDO $db,array $u,int $org,string $key):void
    {
        $r=self::reviewed($u,$org,$key);$v=$r['preview'];$fresh=CommercePricingService::preview($db,$u,$org,$v['production'],$v['mode'],$v['ids'],$v['prices'],$v['reason'],$v['acknowledge']);$stale=!hash_equals($v['hash'],$fresh['hash']);echo '<h3>Review affected performances</h3><p>'.count($v['rows']).' performances · '.self::e($v['mode']).'</p><p>Reason: '.self::e($v['reason']).'</p>';foreach($v['rows'] as $row)echo '<div class="commerce-record"><strong>'.self::e($row['showtime']).'</strong><p>'.$row['orders'].' existing orders keep their saved prices.</p><p>Before: '.self::priceText($row['prices']).'</p></div>';echo '<h3>New prices</h3><p>'.self::priceText($v['prices']).'</p>';if($v['mode']==='defaults')echo '<p>Updates the production default and all listed future inheriting performances. Overrides and past performances are unchanged.</p>';if($stale)echo '<p role="alert">The scope or pricing changed. Start a fresh review.</p>';else{CommerceExperience::form('pricing_apply',['review_key'=>$key]);echo '<button>Apply reviewed pricing</button></form>';}echo self::link('pricing','Back to pricing',['production'=>$v['production']],true);
    }
    public static function priceText(array $prices):string
    {$parts=[];foreach($prices as $zone=>$categories)foreach($categories as $category=>$minor)$parts[]=self::e($zone.' / '.$category).' '.number_format($minor/100,2);return implode(' · ',$parts);}
    private static function salesVersion(array $p):string{return hash('sha256',json_encode([$p['prices_json'],$p['sales_status'],$p['checkin_enabled'],$p['fee_minor'],$p['tax_basis_points'],$p['discount_minor'],$p['schedule_status']],JSON_THROW_ON_ERROR));}
    public static function command(PDO $db,array $u,int $org,string $action):string
    {
        CommerceAccess::demand($db,$u,$org,'inventory');if($action==='production_sales'){$id=(int)($_POST['id']??0);CommerceStore::tx($db,function()use($db,$u,$org,$id){$p=CommerceStore::row($db,'performances',$org,$id,true);if(!hash_equals(self::salesVersion($p),(string)($_POST['expected']??'')))throw new RuntimeException('Performance settings changed. Reload before saving.');CommerceInventoryService::configureLocked($db,$u,$org,$id,json_decode($p['prices_json'],true),(string)($_POST['sales']??''),!empty($_POST['checkin']),(int)($_POST['fee']??0),(int)($_POST['tax']??0),(int)($_POST['discount']??0));});return CommerceExperience::url('performance',['id'=>$id]);}if($action==='pricing_review'){$mode=(string)($_POST['pricing_mode']??'');$preview=CommercePricingService::preview($db,$u,$org,(int)($_POST['production']??0),$mode,(array)($_POST['performances']??[]),$mode==='inherit'?[]:CommercePricingService::parse((array)($_POST['price_rows']??[])),(string)($_POST['reason']??''),!empty($_POST['acknowledge_orders']));$key=bin2hex(random_bytes(16));$_SESSION['commerce_price_reviews']??=[];if(count($_SESSION['commerce_price_reviews'])>=20)array_shift($_SESSION['commerce_price_reviews']);$_SESSION['commerce_price_reviews'][$key]=['org'=>$org,'actor'=>(int)$u['id'],'created'=>time(),'preview'=>$preview];return CommerceExperience::url('pricing',['production'=>$preview['production'],'pricing_review'=>$key]);}
        $key=(string)($_POST['review_key']??'');$r=self::reviewed($u,$org,$key);CommercePricingService::apply($db,$u,$org,$r['preview'],$r['preview']['hash'],$key);$_SESSION['commerce_notice']='Reviewed pricing applied. Existing order snapshots were preserved.';return CommerceExperience::url('performances',['q'=>'']);
    }
    public static function management(PDO $db,array $u,int $org,int $id):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');$p=CommerceStore::row($db,'performances',$org,$id);$groups=CommerceProductionService::productions($db,$u,$org);$show=null;$production=null;foreach($groups as $group)foreach($group['shows'] as $candidate)if((int)$candidate['id']===$id){$show=$candidate;$production=$group;}if(!$show)throw new RuntimeException('Performance unavailable.');
        echo '<div data-production-drawer><h2>Manage performance</h2><h3>'.self::e($production['title']).'</h3><p>'.self::e(CommercePerformancePolicy::label($p)).'</p><p>'.self::e($show['venue'].' / '.$show['space_name']).'</p><p class="commerce-status">'.self::e($show['readiness']).'</p><p>'.$show['sold'].' / '.$show['capacity'].' sold · '.$show['sellable'].' sellable · '.$show['held'].' held · '.$show['blocked'].' allocated</p><details open><summary>Sales status & readiness</summary><p>'.self::e($show['problem']??'Scheduled, published and available for ticket sales.').'</p>';CommerceExperience::form('production_sales',['id'=>$id,'expected'=>self::salesVersion($p)]);echo '<div class="commerce-columns"><label>Sales<select name="sales"><option value="closed">Closed</option><option value="open" '.($p['sales_status']==='open'?'selected':'').'>Open</option></select></label><label><input type="checkbox" name="checkin" '.($p['checkin_enabled']?'checked':'').'> Door check-in enabled</label></div><details><summary>Fees, tax & discount</summary>';CommerceExperience::input('fee','Order fee (cents)','number',(string)$p['fee_minor'],'min="0" max="100000" required');CommerceExperience::input('tax','Tax basis points (600 = 6%)','number',(string)$p['tax_basis_points'],'min="0" max="10000" required');CommerceExperience::input('discount','Order discount (cents)','number',(string)$p['discount_minor'],'min="0" max="1000000" required');echo '</details><button>Save sales settings</button></form></details><details><summary>Pricing</summary><p>'.self::priceText(json_decode($p['prices_json'],true)).'</p>';
        $binding=CommercePricingService::ready($db)?self::rows($db,'SELECT pricing_mode FROM commerce_performance_pricing WHERE organization_id=? AND performance_id=?',[$org,$id]):[];echo '<p>'.(!empty($binding)&&$binding[0]['pricing_mode']==='inherit'?'Inherits production defaults':'Performance override').'</p>'.self::link('pricing','Edit pricing / inheritance',['production'=>$p['production_id'],'id'=>$id],true).'</details><details><summary>Seat blocks & availability</summary><p>'.$show['free'].' free positions before sales restrictions. Held and sold positions remain protected.</p>'.self::link('blocks','Manage visual seat blocks',['production'=>$p['production_id'],'id'=>$id]).'</details><details><summary>Existing orders</summary>';
        if(CommerceAccess::can($db,$u,$org,'report')){foreach(self::rows($db,'SELECT public_reference,customer_name,state,total_minor,currency FROM commerce_orders WHERE organization_id=? AND performance_id=? ORDER BY id DESC LIMIT 5',[$org,$id]) as $order)echo '<div class="commerce-record">'.self::link('orders',$order['customer_name']?:'Walk-up customer',['reference'=>$order['public_reference']],true).'<small> · '.self::e($order['state']).' · '.self::money((int)$order['total_minor'],$order['currency']).'</small></div>';echo self::link('orders','Open all orders for this performance',['performance'=>$id]);}else echo '<p>Order reporting permission is required.</p>';echo '</details><details><summary>Cancellation & administrative actions</summary>';CommercePlanningExperience::showtimeControls($db,$u,$org,$p);CommerceExperience::form('seating_mode',['id'=>$id]);echo '<label>Seating mode<select name="mode"><option value="reserved" '.($p['seating_mode']==='reserved'?'selected':'').'>Reserved seating</option><option value="general_admission" '.($p['seating_mode']==='general_admission'?'selected':'').'>General admission</option></select></label><p>Seating mode cannot change after any order history.</p><button>Save seating mode</button></form>';if(CommerceAccess::can($db,$u,$org,'configure')){$approved=self::rows($db,'SELECT preview_approved FROM commerce_storefront_performances WHERE organization_id=? AND performance_id=?',[$org,$id]);CommerceExperience::form('preview_approve',['id'=>$id]);echo '<label><input type="checkbox" name="approved" value="1" '.(!empty($approved[0]['preview_approved'])?'checked':'').'> Approve restricted storefront preview</label><button>Save preview approval</button></form>';}echo '</details></div>';
    }
}
